chapter(4, 'Maintenance work orders on the phone', 'Follow a repair from the request to a completed work order as the technician.', 'Joseph (Maintenance)', 'maint', menu='Housekeeping & Maintenance > Maintenance', display='mobile')
step('Joseph opens Housekeeping & Maintenance and then Maintenance. The page is My work orders.', 'The technician sees his jobs and no hotel money.', target='sel:main', auto=['click:menutop:Housekeeping & Maintenance', 'click:menuleaf:Maintenance'], action='click', expect='My work orders opens.', check="ctx.page==='maintenance'")
read('The chips To do, On hold and Finished filter the jobs. Each card shows the priority, the location and the buttons Complete, Hold for parts, Add part and Details & history.', 'The priority tells him which job comes first.', target='btn:To do', expect='The work order cards.')
click('btn:Create work order', 'A repair request waits below the jobs. Tap Create work order.', 'A request becomes a tracked job with a priority and a service-level clock.', expect='A work order is created.')
click('btn:Report fault', 'Tap Report fault.', 'The technician can report a fault he finds himself.', expect='The Report a fault sheet opens.')
press('Escape', 'Close the sheet; nothing is reported now.', 'Nothing is saved until you tap the button.', target='sel:main', expect='The work orders are shown.')
click('btn:Add part', 'Tap Add part on the first job.', 'Parts are booked against the job so stock stays right.', expect='The Add part used sheet opens.', check="has('Book part')")
step('Choose the first spare in the list.', 'Booking reduces the spares stock at once.', target='modalbtn:Book part', auto=['select:field:Spare|AC filter mesh'], action='select', expect='The spare is selected.')
click('modalbtn:Book part', 'Tap Book part.', 'The spare is taken from the spares stock.', expect='The part is booked.')
click('btn:Complete', 'Tap Complete.', 'A job is closed with a note.', expect='The Complete work sheet opens.', check="has('Mark complete')")
typ('field:What did you do', 'Cleaned the drain and tested for leaks.', 'Write what you did: Cleaned the drain and tested for leaks.', 'The note is the history of the room.', expect='The note is filled.')
click('modalbtn:Mark complete', 'Tap Mark complete.', 'The job moves to Finished and waits for the check of the supervisor.', expect='The job is complete.')
